  'getLiveState',
  async (
    ctx: RayfinContext<NoTables, AudienceType.Fabric>
  ): Promise<string> => {
    const access: Access = {
      fabricToken: () => ctx.Tokens.Fabric,
      kustoToken: () => { throw new Error('none: a custom audience needs an app with its own identity'); },
      fetch,
    };
